    out = []
    for op in ops:
        k = op[0]
        if k == 'open':
            if op[1] in acct:
                out.append(False)
            else:
                acct[op[1]] = op[2]; out.append(True)
        elif k == 'deposit':
            if op[1] in acct:
                acct[op[1]] += op[2]; out.append(True)
            else:
                out.append(False)
        elif k == 'withdraw':
            if op[1] in acct and acct[op[1]] >= op[2]:
                acct[op[1]] -= op[2]; out.append(True)
            else:
                out.append(False)
